<script lang="ts">
    import { t } from "$lib/i18n/typedI18n";
    import StyledButton from "$lib/components/ui/StyledButton.svelte";
    import SvgIcons from "$lib/components/SvgIcons.svelte";
    import type { FeedbackType } from "$lib/services/feedbackService";

    interface Props {
        selectedType: FeedbackType | null;
        pageLocation: string;
        isSubmitting: boolean;
        textContent: string;
        actualResult: string;
        expectedResult: string;
        onback: () => void;
        onsubmit: () => void;
    }

    let {
        selectedType,
        pageLocation = $bindable(),
        isSubmitting,
        textContent = $bindable(),
        actualResult = $bindable(),
        expectedResult = $bindable(),
        onback,
        onsubmit,
    }: Props = $props();
</script>

<div class="form-container">
    {#if selectedType === "improvement" || selectedType === "bug"}
        <div class="form-group">
            <label for="fb-page">{$t("ui.feedback.pageLabel")}</label>
            <input
                id="fb-page"
                type="text"
                bind:value={pageLocation}
                class="glass-input"
            />
        </div>
    {/if}

    {#if selectedType === "improvement"}
        <div class="form-group">
            <label for="fb-text">{$t("ui.feedback.improvementLabel")} *</label>
            <textarea
                id="fb-text"
                bind:value={textContent}
                class="glass-input textarea-resize"
                rows="4"
            ></textarea>
        </div>
    {/if}

    {#if selectedType === "reward_suggestion"}
        <div class="form-group">
            <label for="fb-reward">{$t("ui.feedback.rewardLabel")} *</label>
            <textarea
                id="fb-reward"
                bind:value={textContent}
                class="glass-input textarea-resize"
                rows="5"
                placeholder="Наприклад: 'Майстер захисту' - виграти гру, не втративши жодного очка..."
            ></textarea>
        </div>
    {/if}

    {#if selectedType === "bug"}
        <div class="form-group">
            <label for="fb-actual"
                >{$t("ui.feedback.actualResultLabel")} *</label
            >
            <textarea
                id="fb-actual"
                bind:value={actualResult}
                class="glass-input textarea-resize"
                rows="3"
            ></textarea>
        </div>
        <div class="form-group">
            <label for="fb-expected"
                >{$t("ui.feedback.expectedResultLabel")} *</label
            >
            <textarea
                id="fb-expected"
                bind:value={expectedResult}
                class="glass-input textarea-resize"
                rows="3"
            ></textarea>
        </div>
    {/if}

    {#if selectedType === "other"}
        <div class="form-group">
            <label for="fb-desc">{$t("ui.feedback.descriptionLabel")} *</label>
            <textarea
                id="fb-desc"
                bind:value={textContent}
                class="glass-input textarea-resize"
                rows="5"
            ></textarea>
        </div>
    {/if}

    <div class="actions-row">
        <StyledButton
            variant="default"
            size="default"
            onclick={onback}
            disabled={isSubmitting}
        >
            {#snippet icon()}
                <SvgIcons name="arrow-left" width="18" height="18" />
            {/snippet}
            {$t("ui.goBack")}
        </StyledButton>
        <StyledButton
            variant="primary"
            size="default"
            onclick={onsubmit}
            disabled={isSubmitting}
        >
            {isSubmitting ? $t("common.loading") : $t("ui.feedback.submit")}
        </StyledButton>
    </div>
</div>

